using UnityEngine;
namespace Blocklands {
 public partial class CastleSystem {
  Transform rescue,royalRide;Vector3 transportStart,rideLast;float rescueAt,treatmentUntil,rideAt;bool treatment,riding;public bool TransportActive=>rescue!=null||treatment||riding;public bool RideWaiting=>royalRide!=null&&!riding;
  void BuildRoyalFacilities(){BuildThroneTV();BuildHospital();BuildPolice();BuildForestShop();if(Game.RoyalIdentity&&palacePrincess!=null)palacePrincess.gameObject.SetActive(false);}
  void BuildHospital(){var root=new GameObject("粉晶皇家医院内部").transform;root.SetParent(transform);root.position=new Vector3(55,16,9);var a=root.gameObject.AddComponent<RoyalArt>();Color white=new Color(.92f,.95f,.97f),blue=new Color(.25f,.68f,.82f),steel=new Color(.55f,.65f,.7f);a.Piece("诊疗仪",new Vector3(2,1.2f,0),new Vector3(1.2f,2.4f,.7f),steel);a.Piece("心跳屏",new Vector3(2,1.55f,-.38f),new Vector3(.8f,.55f,.05f),new Color(.15f,.7f,.55f));a.Piece("消毒台",new Vector3(-2,.6f,0),new Vector3(1.4f,1.2f,.7f),white);for(int i=0;i<5;i++)a.Piece("消毒瓶",new Vector3(-2.45f+i*.22f,1.3f,0),new Vector3(.12f,.3f,.12f),Color.HSVToRGB(i*.16f,.35f,.9f),PrimitiveType.Cylinder);a.Piece("药品柜",new Vector3(0,1.5f,4),new Vector3(5,3,.5f),white);a.Piece("听诊器",new Vector3(1.8f,1.1f,.38f),new Vector3(.08f,.8f,.08f),blue,PrimitiveType.Capsule);
   for(int i=0;i<4;i++){var doctor=new GameObject("医生 "+(i+1)).transform;doctor.SetParent(root,false);doctor.localPosition=new Vector3(-3+i*2,0,-2+i%2*4);var d=doctor.gameObject.AddComponent<RoyalArt>();d.Piece("白大褂",new Vector3(0,1,0),new Vector3(.62f,.95f,.42f),white);d.Piece("医生头",new Vector3(0,1.75f,0),new Vector3(.52f,.55f,.48f),new Color(.87f,.65f,.5f),PrimitiveType.Sphere);foreach(float x in new[]{-.12f,.12f})d.Piece("眼睛",new Vector3(x,1.8f,.24f),Vector3.one*.06f,Color.black,PrimitiveType.Sphere);d.Piece("听诊器",new Vector3(0,1.2f,.24f),new Vector3(.28f,.35f,.05f),blue,PrimitiveType.Cylinder);}
  }
  void BuildPolice(){var root=new GameObject("森林警察局内部").transform;root.SetParent(transform);root.position=new Vector3(55,16,46);for(int i=0;i<3;i++){var officer=new GameObject("警察 "+(i+1)).transform;officer.SetParent(root,false);officer.localPosition=new Vector3(i*1.5f,0,0);var a=officer.gameObject.AddComponent<RoyalArt>();a.Piece("警服",new Vector3(0,1,0),new Vector3(.65f,.9f,.4f),new Color(.12f,.25f,.55f));a.Piece("警察头",new Vector3(0,1.75f,0),new Vector3(.5f,.52f,.46f),new Color(.86f,.64f,.49f),PrimitiveType.Sphere);a.Piece("警帽",new Vector3(0,2.03f,0),new Vector3(.58f,.12f,.5f),new Color(.08f,.15f,.35f));}}
  void BuildForestShop(){var root=new GameObject("森林小卖部内部").transform;root.SetParent(transform);root.position=new Vector3(8,16,7);var clerk=RoyalArt.Girl(root,false,false);clerk.gameObject.name="森林小卖部店员";clerk.transform.localPosition=new Vector3(0,0,2);var a=root.gameObject.AddComponent<RoyalArt>();Color wood=new Color(.54f,.33f,.17f);a.Piece("大柜台",new Vector3(0,.55f,1),new Vector3(5,1.1f,.8f),wood);for(int row=0;row<4;row++)for(int col=0;col<6;col++){int i=row*6+col;Vector3 p=new Vector3((col-2.5f)*.75f,.5f+row*.65f,3.2f);a.Piece("商品 "+(i+1),p,Vector3.one*.36f,Blocks.ColorOf(Sandbox.Offers[0][i].Item));}}
  Transform Carriage(string name,Vector3 position){var c=new GameObject(name).transform;c.SetParent(transform);c.position=position;var a=c.gameObject.AddComponent<RoyalArt>();Color pink=new Color(.93f,.44f,.7f),gold=new Color(1,.75f,.25f);a.Piece("软垫",new Vector3(0,.75f,0),new Vector3(2.8f,.4f,1.8f),pink);a.Piece("顶棚",new Vector3(0,2.8f,0),new Vector3(3.1f,.24f,2.1f),pink);foreach(float x in new[]{-1.25f,1.25f})foreach(float z in new[]{-.75f,.75f})a.Piece("金柱",new Vector3(x,1.8f,z),new Vector3(.1f,2,.1f),gold);for(int i=0;i<4;i++){var guard=new GameObject("忠诚抬轿卫兵").transform;guard.SetParent(c,false);guard.localPosition=new Vector3(i<2?-2:2,0,i%2==0?-1:1);var g=guard.gameObject.AddComponent<RoyalArt>();g.Piece("制服",new Vector3(0,1,0),new Vector3(.62f,.9f,.4f),new Color(.14f,.27f,.6f));g.Piece("头",new Vector3(0,1.72f,0),new Vector3(.5f,.5f,.45f),new Color(.86f,.64f,.49f),PrimitiveType.Sphere);}FurnishCarriage(c);return c;}
  public void CompleteSuccession(CrownChallenge duel){Game.RoyalIdentity=true;CrownedPrincess();SuppressFormerPrincess();foreach(var c in GetComponentsInChildren<CrownChallenge>(true))c.gameObject.SetActive(false);if(palacePrincess!=null)palacePrincess.gameObject.SetActive(false);Game.Save();rescue=Carriage("卫兵护送公主去医院",Game.Player.transform.position);transportStart=rescue.position;rescueAt=Time.time;Game.Notice="挑战成功！你成为公主。卫兵正在把受伤的你送往皇家医院。";}
  public void CallRoyalRide(){if(sunStage!=0){Game.Notice="阳台休息流程中，请使用5返回。";return;}if(!Game.RoyalIdentity){Game.Notice="完成公主挑战后才能呼叫皇家轿子。";return;}if(TransportActive&&!RideWaiting){Game.Notice="先完成当前治疗或巡游。";return;}if(royalRide==null){royalRide=Carriage("公主专属森林巡游轿",new Vector3(31.5f,16,10));Game.Notice="卫兵已在城门等候。乘电梯下一楼，到轿子旁按Q上轿。";return;}if(!riding&&Vector3.Distance(Game.Player.transform.position,royalRide.position)<5&&Game.Player.transform.position.y<23){riding=true;rideAt=Time.time;rideLast=royalRide.position;Game.Player.Teleport(royalRide.position+Vector3.up*1.2f);Game.Notice="四名卫兵抬起轿子，开始森林巡游。";}else Game.Notice="轿子在城门外，先坐电梯下一楼并靠近它。";}
  void RoyalCareUpdate(){if(rescue!=null){float t=Mathf.Clamp01((Time.time-rescueAt)/5);Vector3 goal=Vector3.Lerp(transportStart,new Vector3(56,16,7),t);Vector3 delta=goal-rescue.position;rescue.position=goal;Game.Player.Carry(delta);if(t>=1){Destroy(rescue.gameObject);rescue=null;treatment=true;treatmentUntil=Time.time+10;Game.Player.Teleport(new Vector3(56,16.2f,9));Game.Notice="医生正在清洗伤口、消毒、检查并治疗，10秒后恢复满血。";}return;}if(treatment){Game.HealRoyal(Time.deltaTime);if(Time.time>=treatmentUntil){treatment=false;Game.HealRoyal(99);Game.Notice="治疗完成，生命恢复满格。C或Fn+F6查看皇冠公主外观，Q呼叫轿子。";}return;}if(riding&&royalRide!=null){float age=Time.time-rideAt;Vector3 p=new Vector3(31.5f+Mathf.Sin(age*.22f)*23,16,10+Mathf.Sin(age*.44f)*5);Vector3 delta=p-royalRide.position;royalRide.position=p;Game.Player.Carry(delta);if(age>28){riding=false;Game.Player.Teleport(new Vector3(31.5f,16,11));Destroy(royalRide.gameObject);royalRide=null;Game.Notice="森林巡游结束，卫兵把你送回城门。";}}}
 }
 public partial class Sandbox {bool forestShopOpen;Vector2 forestShopScroll;public bool RoyalTransportActive=>castle!=null&&(castle.TransportActive||castle.PlayerSunLocked);public bool Bleeding=>Health<10;
  public void HealRoyal(float amount){Health=Mathf.Min(10,Health+amount);}
  bool ForestShopKey(){if(World.Region!=6)return false;if(Input.GetKeyDown(KeyCode.X)&&Vector3.Distance(Player.transform.position,new Vector3(8,16,5))<8){forestShopOpen=true;SetPaused(true);Notice="森林小卖部 · 24种商品";return true;}return false;}
  void DrawForestShop(float w,float h){float x=w/2-320,y=h/2-245;Panel(new Rect(x,y,640,490),new Color(.94f,.9f,.8f));Label(new Rect(x+24,y+20,590,34),"森林小卖部 · 店员柜台 · 24种商品",23,new Color(.18f,.22f,.2f));Label(new Rect(x+24,y+60,590,26),"绿色钱包："+Inventory[(int)Block.Coin]+"元 · 点击购买",16,new Color(.35f,.38f,.34f));forestShopScroll=GUI.BeginScrollView(new Rect(x+24,y+96,592,320),forestShopScroll,new Rect(0,0,566,528));for(int i=0;i<Offers[0].Length;i++){var o=Offers[0][i];if(LiftMenuButton(new Rect(i%2*283,i/2*44,275,38),Blocks.Names[(int)o.Item]+" × "+o.Amount+" — "+o.Price+"元",false)){if(Inventory[(int)Block.Coin]>=o.Price&&Inventory[(int)o.Item]<=9999-o.Amount){Inventory[(int)Block.Coin]-=o.Price;Inventory[(int)o.Item]+=o.Amount;Save();}else Notice="钱币不足或背包已满。";}}GUI.EndScrollView();if(GUI.Button(new Rect(x+24,y+435,592,35),"离开小卖部 · Esc")){forestShopOpen=false;SetPaused(false);}}
 }
}
